def parse_section(txt, marker, stop):
    part=txt.split(marker,1)[1].split(stop,1)[0]
    lines=part.strip().splitlines()
    grid=[]
    for line in lines:
        vals=[int(x) for x in line.split() if x.isdigit()]
        if len(vals)==24: grid.append(vals)
    return grid
