def predict_layers(inp):
    import numpy as np
    a=np.array(inp); bg=int(a[0,0]); out=a.copy()
    panels={}
    for r in range(a.shape[0]):
        fill=int(a[r,1]); edge=int(a[r,0])
        if a[r,0]==a[r,-1] and np.all(a[r,1:-1]==fill) and edge!=fill and fill!=bg:
            panels.setdefault(fill, []).append(r)
    bands={}
    for fill, rr in panels.items():
        groups=[]
        for r in rr:
            if not groups or r!=groups[-1][-1]+1: groups.append([r])
            else: groups[-1].append(r)
        bands[fill]=(groups[-1][0],groups[-1][-1],int(a[groups[-1][0],0]))
    topend=min(v[0] for v in bands.values())
    for color in set(int(x) for x in a[:topend,:].flat if int(x)!=bg):
        if color not in bands: continue
        mask=(a[:topend,:]==color)
        lab,n=label(mask)
        yb,ye,edge=bands[color]
        for k in range(1,n+1):
            ys,xs=np.where(lab==k)
            h=ys.max()-ys.min()+1
            dy=ye-h+1-ys.min()
            for y,x in zip(ys,xs): out[y+dy,x]=edge
    out[:topend,:]=bg
    return out.tolist(),bands
